# generate vimdoc txt
panvimdoc.sh \
    --project-name 'dove' \
    --input-file 'docs/dove.md' \
    --vim-version 'NVIM v0.12.0' \
    --description 'Use Lua to define and run shell commands or Lua code anywhere.' \
    --toc 'true' \
    --treesitter 'true'

# remove generated by panvimdoc information
sed -i '/^Generated by panvimdoc /d' doc/dove.txt

# generate vimdoc tags
nvim --headless -u NONE -c 'helptags doc' -c 'qa'
